from lib import *
S = SS('j280')
steps = [
    step("转换后数据库里存的是什么(Hibernate 6.6.4 + PostgreSQL 16):实体 Doc 有 Set<String> tags(自写 CsvConverter 转成逗号分隔字符串)、LocalDate day(转成 yyyymmdd 整数)、Boolean archived 与基本类型 boolean pinned(autoApply 的 YN 转换器)。原生 SQL 读到:tags = java,jpa,sql(varchar)、day = 20261005(int4)、archived = Y(varchar)、pinned = N(varchar)。autoApply 的 Boolean 转换器对基本类型 boolean 也生效了;find 回来 tags = [java, jpa, sql]、day = 2026-10-05、archived = true。", t=tl(S(1)), done=lidx(S(1), '原生 SQL 读到的列', '列类型'), mark=lidx(S(1), 'find 回来'), kv=KV([['Set<String>', 'varchar:java,jpa,sql'], ['LocalDate', 'int4:20261005'], ['Boolean 与 boolean(autoApply)', 'varchar:Y / N']], ['Boolean 与 boolean(autoApply)'])),
    step("null 与空值:persist 一个 tags / day / archived 全为 null 的实体,两个自写转换器的 convertToDatabaseColumn 被调用 2 次(参数都是 null),需要自己处理 null;库里是 NULL;读回来时 convertToEntityAttribute 也被调用 2 次(参数 null),三个字段都是 null。空集合 new HashSet<>() 存进去,库里是空串(不是 NULL),读回来 tags = [](不是 null,size = 0)。转换器决定了“空”与“null”在数据库里是否可区分。", t=tl(S(2)), done=lidx(S(2), 'persist 一个 tags', '库里的值'), mark=lidx(S(2), 'find 回来', '空集合', '读回来'), kv=KV([['转换器对 null', '会被调用,参数为 null,要自己处理'], ['空集合', '存成空串,读回来是空集合(不是 null)']], ['转换器对 null'])),
    step("脏检查:被转换的是可变对象 Set。find 之后直接 m.tags.add(\"new-tag\")(原地修改)commit:新增 1 条 SQL,库里 tags = java,jpa,new-tag,sql——原地修改能被发现;换成内容完全相同的新 Set 对象:0 条 SQL(按转换后的值比较);换成多了 x2 的新 Set 对象:1 条 SQL,库里变成 …,sql,x2;LocalDate 赋成一个相等的新对象:0 条 UPDATE。Hibernate 6.6 对转换器的字段用转换后的值做脏检查。", t=tl(S(3)), done=lidx(S(3), '原地修改', '换成一个内容完全相同'), mark=lidx(S(3), '多了 x2', 'LocalDate(不可变类型)'), kv=KV([['原地修改 Set', '能发现,发出 UPDATE'], ['内容相同的新对象', '0 条 SQL'], ['内容不同的新对象', '1 条 UPDATE']], ['原地修改 Set'])),
    step("转换器被调用的次数:加载 1000 个实体:convertToDatabaseColumn 1000 次、convertToEntityAttribute 3000 次(每个实体 1 次转回数据库值、3 次转回实体值——快照与可变类型的复制也会调用);没有任何修改时 flush:0 / 0;改了一个实体的 tags 之后 flush:convertToDatabaseColumn 3 次、convertToEntityAttribute 1 次;persist 100 个实体并 flush:convertToDatabaseColumn 300 次、convertToEntityAttribute 100 次。转换器要写成无副作用、轻量的纯函数,因为它被调用的次数比字段数多。", t=tl(S(4)), done=lidx(S(4), '加载 1000 个实体', '没有任何修改时 flush'), mark=lidx(S(4), '改了一个实体的 tags', 'persist 100 个实体'), b=bars([['加载 1000 个:toEntity 调用', 3000, '3000'], ['加载 1000 个:toDb 调用', 1000, '1000'], ['persist 100 个:toDb 调用', 300, '300'], ['无修改 flush', 0, '0']], 3000, done=[0, 1, 2, 3]), kv=KV([['加载 N 个实体', 'toDb 约 N 次,toEntity 约 3N 次(每个含两个转换器的实体)'], ['无修改 flush', '0 次调用'], ['persist N 个', 'toDb 3N 次,toEntity N 次']], ['加载 N 个实体'])),
    step("查询里的转换:参数 d.archived = :a(true)命中 1 行(参数被转换成 Y);字面量 d.archived = true 命中 1 行(字面量也被转换);参数 d.day = :day(LocalDate)命中 1 行(转成 20261005);范围比较 d.day >= :a and d.day < :b 命中 1002 行(yyyymmdd 整数保持了日期顺序,可以做范围查询);d.tags like :p 抛 QueryArgumentException(参数 String 与参数类型 Set 不匹配)——转换后的列在 JPQL 里仍然是 Set,不能当字符串用;投影 select d.day, d.archived 返回 LocalDate 与 Boolean(被转换回实体字段类型)。", t=tl(S(5)), done=lidx(S(5), 'd.archived = :a', 'd.archived = true', 'd.day = :day'), mark=lidx(S(5), '范围比较', 'd.tags like :p', '投影'), kv=KV([['参数 / 字面量', '都会被转换'], ['范围比较', '整数保持顺序时可用'], ['like 在转换后的字段上', 'QueryArgumentException']], ['like 在转换后的字段上'])),
    step("数据库里的值无法转换回来时:去掉检查约束后把 archived 改成 'X':find 读到这一行抛 PersistenceException ← IllegalArgumentException(转换器自己抛的“无法识别的值”);不读取该列的聚合查询 count(d) 正常返回 1003 行;select d from Doc d(包含坏行)整个查询失败。一行坏数据会让所有读到它的查询失败,转换器里的异常没有被隔离。", t=tl(S(6)), done=lidx(S(6), "find 读到 archived = 'X' 的行"), mark=lidx(S(6), 'count(d)', 'select d from Doc d(包含坏行)'), kv=KV([['读取坏行', 'PersistenceException ← IllegalArgumentException'], ['不读该列的 count(d)', '不受影响'], ['select d from Doc d', '整个查询失败']], ['读取坏行'])),
]
A = mkartj('j280', 280, 'Java,JPA,Hibernate,AttributeConverter,类型转换,PostgreSQL,真实验证,动画演示',
    '在 Hibernate 6.6.4 + 真实 PostgreSQL 上实测 AttributeConverter:autoApply 也应用到基本类型 boolean;转换器要自己处理 null,空集合存成空串;原地修改被转换的 Set 能被脏检查发现;加载 1000 个实体 toEntity 被调用 3000 次;参数与字面量都会转换,like 不能用在被转换的字段上;库里出现无法识别的值会让读到它的查询失败。',
    'AttributeConverter 让实体字段与数据库列可以是不同的类型,但转换器的调用次数、null 处理、脏检查和查询里的行为都有细节。这篇用真实的数据库内容与调用计数量出这些行为。',
    [('3000 次', '加载 1000 个含两个转换器字段的实体时 convertToEntityAttribute 的调用次数(convertToDatabaseColumn 1000 次)'), ('空串 ≠ NULL', '空集合经 CsvConverter 存进数据库的值与 null 集合存进数据库的值'), ('整个查询失败', '库里一行 archived = \'X\' 时,读到它的 select d from Doc d 的结果(count(d) 不受影响)')],
    [('转换后的数据库值', None), ('null 与空值', None), ('脏检查', None), ('调用次数', None), ('查询里的转换', None), ('无法转换的值', None)],
    steps, [ENV_J + '。Hibernate ORM 6.6.4.Final、PostgreSQL JDBC 42.7.4、本机 PostgreSQL 16.15;两个转换器是自写的(计数用静态计数器);hbm2ddl 自动为 Y/N 列生成了检查约束(第 6 步先删除了它)', '没有验证:@Convert 用在集合元素 / Map 键、@Convert 与 @Enumerated 的冲突、Hibernate 的 @JavaType / @JdbcType 替代方案、转换器内注入 Spring Bean、其它数据库(Oracle / MySQL)上的 Boolean 列类型、JSON 列的转换'], 'AttributeConverter')
